"""Full trainable MLP→GAT→pooled graph/price→attention LSTM path."""
from __future__ import annotations
import torch
from types import MappingProxyType
from torch import nn
from torch.utils.checkpoint import checkpoint
from .gat import GraphAttention
from .pooling import mean_pool
from .temporal import TemporalHead,initialize_linear


def validate_execution(value):
    """Explicit execution metadata, separate from scientific model config."""
    if value is None:return None
    if type(value) is not dict or set(value)!={'schema_version','backend','block_edges'}:
        raise ValueError('model execution policy fields differ')
    if type(value['schema_version']) is not int or value['schema_version']!=1 or value['backend']!='streamed-gat-mulsum-v1':
        raise ValueError('model execution backend/schema differs')
    if type(value['block_edges']) is not int or not 0<value['block_edges']<=65536:
        raise ValueError('model execution block bound differs')
    return MappingProxyType(dict(value))


class GraphEncoder(nn.Module):
    def __init__(self,config,*,execution=None):
        selected=validate_execution(execution)
        super().__init__();self.config=dict(config)
        self.execution=selected
        layer=GraphAttention;extra={}
        if selected is not None:
            from .streamed_gat import GraphAttention as StreamedGraphAttention
            layer=StreamedGraphAttention;extra={'block_edges':selected['block_edges']}
        widths=[config['mcm_input'],*config['mlp_widths']]
        blocks=[]
        for a,b in zip(widths,widths[1:]):
            linear=nn.Linear(a,b);initialize_linear(linear);blocks.extend([linear,nn.ReLU()])
        self.mlp=nn.Sequential(*blocks)
        layers=[];width=widths[-1]
        for heads,out,concat,activation in zip(config['gat_heads'],config['gat_widths'],config['gat_concatenate'],config['gat_activation'],strict=True):
            layers.append(layer(width,out,heads,concat=concat,activation=activation,dropout=config['gat_dropout'],slope=config['leaky_relu_slope'],**extra))
            width=out*heads if concat else out
        if width!=config['graph_vector_width']:raise ValueError('graph output width mismatch')
        self.gat=nn.ModuleList(layers)

    def forward(self,mcm,edge_index,node_mask=None,batch=None):
        if batch is not None and edge_index.numel() and (batch[edge_index[0]]!=batch[edge_index[1]]).any():raise ValueError('edge crosses graph batch')
        if node_mask is not None:
            if node_mask.shape!=(len(mcm),) or node_mask.dtype!=torch.bool:raise ValueError('invalid node mask')
            mcm=mcm.masked_fill(~node_mask[:,None],0.)
        if not torch.isfinite(mcm).all():raise ValueError('nonfinite admitted MCM')
        h=self.mlp(mcm)
        for layer in self.gat:h=layer(h,edge_index,node_mask)
        return mean_pool(h,node_mask,batch)


class ReplicationModel(nn.Module):
    def __init__(self,config,task,*,execution=None):
        selected=validate_execution(execution)
        super().__init__();self._configure(config,task)
        self.execution=selected
        self.graph=GraphEncoder(config,execution=None if selected is None else dict(selected))
        self.temporal=TemporalHead(config['graph_vector_width']+config['price_input_width'],config['lstm_width'],config['attention_width'],task,config['lstm_depth'])

    def _configure(self,config,task):
        self.config=dict(config);self.task=task
        policy=config.get('graph_activation_checkpointing',False)
        if type(policy) is not bool:raise ValueError('graph activation checkpointing must be boolean')
        self.graph_activation_checkpointing=policy

    def _encode_graph(self,mcm,edge_index,node_mask=None,batch=None):
        if self.graph_activation_checkpointing and self.training and torch.is_grad_enabled():
            # Non-reentrant mode trains parameters with fixed MCM inputs. Tensor
            # args expose accelerator devices to checkpoint's RNG preservation.
            return checkpoint(self.graph,mcm,edge_index,node_mask,batch,
                              use_reentrant=False,preserve_rng_state=True)
        return self.graph(mcm,edge_index,node_mask,batch)

    def forward(self,graph_sequences,prices,mask=None):
        if prices.ndim!=3 or len(graph_sequences)!=len(prices):raise ValueError('graph/price sequence batch mismatch')
        valid=torch.ones(prices.shape[:2],dtype=torch.bool,device=prices.device) if mask is None else mask
        rows=[];encoded_graphs={}
        for b,sequence in enumerate(graph_sequences):
            if len(sequence)!=prices.shape[1]:raise ValueError('graph/price lookback mismatch')
            vectors=[]
            for t,graph in enumerate(sequence):
                if not valid[b,t]:vectors.append(prices.new_zeros(self.config['graph_vector_width']))
                elif graph is None:raise ValueError('missing valid graph step')
                else:
                    key=id(graph)
                    if key not in encoded_graphs:
                        encoded_graphs[key]=self._encode_graph(**graph)
                    vectors.append(encoded_graphs[key])
            rows.append(torch.stack(vectors))
        embeddings=torch.stack(rows)
        return self.temporal(torch.cat([embeddings,prices],dim=-1),valid)

    def parameter_groups(self):
        return {'mlp':list(self.graph.mlp.parameters()),'gat':list(self.graph.gat.parameters()),
                'lstm':list(self.temporal.lstm.parameters()),
                'attention':list(self.temporal.query.parameters())+list(self.temporal.key.parameters())+list(self.temporal.alignment.parameters()),
                'head':list(self.temporal.output.parameters())}

"""Finite fit engine behind an existing admitted ResearchRun claim."""
from dataclasses import dataclass
from pathlib import Path
import json
import time
import torch
from ..lifecycle import ResearchRun,_lock,_immutable
from .provenance import canonical_bytes,digest,durable_mkdir,sync_directory,file_hash
from .checkpoints import seed_all,save_checkpoint,load_checkpoint
from . import financial_execution as financial


@dataclass
class FitResult:
    model:object
    checkpoint:Path
    checkpoint_hash:str
    logs:list


def _reserve(run,cell_id,provenance,continuation):
    if not isinstance(run,ResearchRun):raise ValueError('admitted ResearchRun required')
    with _lock(run.admission.root):
        run._active();run._check_source()
        if cell_id not in run.admission.experiment['cells']:raise ValueError('unregistered fit cell')
        if provenance['cell_id']!=cell_id or provenance['source_commit']!=run.admission.source:raise ValueError('fit source/cell mismatch')
        root=run.admission.root/'research_artifacts'/'onchain_fit_cells'/digest(cell_id.encode())
        durable_mkdir(root)
        previous=sorted(root.iterdir())
        if previous:
            if continuation is None:raise FileExistsError('fit cell already claimed; explicit new continuation required')
            parent=run.admission.experiment['parent']
            if parent is None or parent==run.admission.experiment_id:raise ValueError('continuation requires new registered parent claim')
            parent_dir=run.admission.root/'research_runs'/parent
            if not (parent_dir/'failed.json').is_file() or (parent_dir/'complete.json').exists():raise ValueError('parent is active or completed; continuation forbidden')
            if len(previous)!=1 or previous[0].name!=parent:raise ValueError('unreviewed continuation chain')
            if not (previous[0]/'failed.json').is_file() or (previous[0]/'complete.json').exists():raise ValueError('parent fit is active or completed; continuation forbidden')
            checkpoint=Path(continuation['checkpoint']).resolve()
            if not checkpoint.is_relative_to(previous[0].resolve()):raise ValueError('checkpoint is not from parent fit')
            if not any(info['sha256']==file_hash(checkpoint) and (run.admission.root/info['path']).resolve()==checkpoint for info in run.admission.inputs.values()):raise ValueError('continuation checkpoint not registered input')
            old=continuation['provenance']
            if {k:v for k,v in old.items() if k!='source_commit'}!={k:v for k,v in provenance.items() if k!='source_commit'}:raise ValueError('continuation scientific provenance mismatch')
        elif continuation is not None:raise ValueError('continuation has no prior fit claim')
        destination=root/run.admission.experiment_id
        destination.mkdir();sync_directory(root)
        _immutable(destination/'claim.json',{'experiment_id':run.admission.experiment_id,'provenance':provenance,'parent_checkpoint':None if continuation is None else str(continuation['checkpoint'])})
        return destination


def fit_cell(run,cell_id,provenance,model_factory,batch_factory,n_examples,task,seed,training_config,*,continuation=None,checkpoint_seconds=600.,after_batch=None):
    """batch_factory supplies registered chronological inputs; no test loss enters fit."""
    if n_examples<=0 or task not in {'regression','classification'}:raise ValueError('invalid fit population/task')
    if training_config['shuffle'] or training_config['scheduler']!='none':raise ValueError('unregistered training schedule')
    if not 0<checkpoint_seconds<=600:raise ValueError('checkpoint interval must be within ten minutes')
    directory=_reserve(run,cell_id,provenance,continuation)
    checkpoint=None
    try:
        rng=seed_all(seed);model=model_factory();financial.check_model(model,provenance.get('model_execution'));model.train()
        optimizer=torch.optim.Adam(model.parameters(),lr=training_config['learning_rate'],betas=tuple(training_config['betas']),eps=training_config['epsilon'],weight_decay=training_config['weight_decay'])
        epoch=0;batch=0;logs=[];loss_sum=0.;count=0;checkpoint=None
        schedule={'training':training_config,'seed':seed,'task':task,'n_examples':n_examples}
        if continuation is not None:
            prior_schedule=Path(continuation['checkpoint']).parents[2]/'schedule.json'
            if canonical_bytes(json.loads(prior_schedule.read_bytes()))!=canonical_bytes(schedule):raise ValueError('continuation training schedule mismatch')
            state=load_checkpoint(continuation['checkpoint'],model,optimizer,rng,continuation['provenance'])
            epoch=state['epoch'];batch=state['batch'];logs=state['logs'];loss_sum=state['epoch_loss'];count=state['epoch_count']
            checkpoint=Path(continuation['checkpoint'])
        size=training_config['batch_size'];epochs=training_config['epochs'];batches=(n_examples+size-1)//size
        if epoch>epochs or batch>=batches or (epoch==epochs and batch):raise ValueError('checkpoint cursor outside registered fit')
        last=time.monotonic()
        _immutable(directory/'schedule.json',schedule)
        while epoch<epochs:
            run._active()
            financial.check_model(model,provenance.get('model_execution'))
            indices=list(range(batch*size,min((batch+1)*size,n_examples)))
            inputs,targets=batch_factory(indices);optimizer.zero_grad(set_to_none=True)
            output=model(**inputs)
            if output.shape[0]!=len(indices) or len(targets)!=len(indices):raise ValueError('batch population changed')
            if task=='regression' and (output.shape!=(len(indices),1) or targets.shape!=output.shape):raise ValueError('regression target shape must equal [batch,1] output')
            if task=='classification' and (output.shape!=(len(indices),2) or targets.shape!=(len(indices),) or targets.dtype!=torch.long):raise ValueError('classification target shape/dtype')
            loss=torch.nn.functional.cross_entropy(output,targets) if task=='classification' else torch.nn.functional.mse_loss(output,targets)
            if not torch.isfinite(loss):raise ValueError('nonfinite training loss')
            loss.backward();torch.nn.utils.clip_grad_norm_(model.parameters(),training_config['gradient_clip_norm'],error_if_nonfinite=True);optimizer.step()
            loss_sum+=float(loss.detach())*len(indices);count+=len(indices);batch+=1
            del inputs,targets,output,loss
            epoch_end=batch==batches
            if epoch_end:
                logs.append({'epoch':epoch,'loss':loss_sum/count,'examples':count,'seed':seed})
                _immutable(directory/f'epoch-{epoch:04d}.json',logs[-1])
                epoch+=1;batch=0;loss_sum=0.;count=0
            if epoch_end or time.monotonic()-last>=checkpoint_seconds:
                checkpoint=save_checkpoint(directory/'checkpoints',model,optimizer,rng,provenance,epoch=epoch,batch=batch,logs=logs,epoch_loss=loss_sum,epoch_count=count);last=time.monotonic()
            if after_batch is not None:after_batch(epoch,batch,checkpoint)
        _immutable(directory/'complete.json',{'checkpoint':str(checkpoint),'sha256':file_hash(checkpoint),'epochs':epoch})
        return FitResult(model,checkpoint,file_hash(checkpoint),logs)
    except BaseException as error:
        _immutable(directory/'failed.json',{'type':type(error).__name__,'reason':str(error),'last_checkpoint':str(checkpoint) if checkpoint else None})
        raise


def predict_cell(model,batch_factory,n_examples,batch_size):
    model.eval();outputs=[]
    with torch.no_grad():
        for start in range(0,n_examples,batch_size):
            inputs,_=batch_factory(list(range(start,min(start+batch_size,n_examples))))
            output=model(**inputs)
            if output.shape[0]!=min(batch_size,n_examples-start):raise ValueError('prediction population changed')
            if not torch.isfinite(output).all():raise ValueError('nonfinite prediction')
            outputs.append(output.detach().cpu())
            del inputs,output
    return torch.cat(outputs)

"""Bounded, descriptor-anchored storage observations for owned output trees.

Allocated bytes are st_blocks * 512, including directories. Logical file bytes
also constrain sparse files. This is sampled accounting, not a kernel filesystem
quota, an atomic snapshot, or a bound on growth between observations. A registered
runner must pair it with bounded writes, checkpoint/event reservations and the
outer free-disk guard, and retain any observed breach as terminal evidence.
"""
from __future__ import annotations
import os
import hashlib
import json
from pathlib import Path
import stat
import time
from types import MappingProxyType

FIELDS={'max_allocated_bytes','max_logical_bytes','max_entries','max_depth','max_scan_seconds'}

class StorageLimit(ValueError):
    def __init__(self,reason,observation):
        super().__init__('storage '+reason+' limit exceeded')
        self.observation=dict(observation)
        self.reason=reason

class HardlinkObservation(ValueError):
    """An incomplete scan saw a link; it is never an accepted observation."""
    def __init__(self,relative,info):
        path=str(relative)
        self.evidence={'relative_path':path[:512],'path_truncated':len(path)>512,
            'path_sha256':hashlib.sha256(os.fsencode(path)).hexdigest(),
            'device':info.st_dev,'inode':info.st_ino,'links':info.st_nlink}
        self.history=[]
        super().__init__('storage hardlink refused: '+json.dumps(self.evidence,sort_keys=True))

class StorageCleanupFailure(RuntimeError):pass


def _cleanup(action,primary=None):
    try:action()
    except BaseException as error:
        if primary is not None:
            primary.add_note('storage descriptor close uncertainty: '+repr(error))
            if not isinstance(primary,Exception) or isinstance(primary,MemoryError):raise primary
        if not isinstance(error,Exception) or isinstance(error,MemoryError):raise error from primary
        failure=StorageCleanupFailure('storage owned close uncertain; no scan retry')
        failure.add_note(repr(error));raise failure from primary

def _close(fd,primary=None):return _cleanup(lambda:os.close(fd),primary)


def _annotate(error,observed,history):
    try:
        old=getattr(error,'observation',observed)
        error.observation={**dict(old),'hardlink_observations':list(history)}
    except BaseException as secondary:
        if not isinstance(error,Exception) or isinstance(error,MemoryError):raise error
        if not isinstance(secondary,Exception) or isinstance(secondary,MemoryError):raise secondary from error
        error.add_note('storage diagnostic attachment unavailable: '+repr(secondary))

class StorageWatch:
    def __init__(self,root,limits):
        if type(limits) is not dict or set(limits)!=FIELDS or any(type(n) is not int or n<=0 for n in limits.values()):
            raise ValueError('positive integer storage limits required')
        if limits['max_depth']>64 or limits['max_scan_seconds']>5:
            raise ValueError('storage traversal depth/time limits too large')
        self.limits=MappingProxyType(dict(limits));self.root=Path(root)
        if not self.root.is_absolute() or self.root.resolve(strict=True)!=self.root:
            raise ValueError('canonical owned storage root required')
        info=self.root.lstat()
        if not stat.S_ISDIR(info.st_mode):raise ValueError('storage root must be a directory')
        self.identity=(info.st_dev,info.st_ino)

    def check(self):
        begin=time.monotonic();history=[]
        try:return self._check(begin,history)
        except BaseException as error:
            prior=getattr(error.__cause__ or error.__context__,'observation',{})
            _annotate(error,prior,history);raise

    def _check(self,begin,history):
        for attempt in range(3):
            if time.monotonic()-begin>self.limits['max_scan_seconds']:
                raise StorageLimit('time',{'hardlink_observations':history})
            try:
                result=self._scan(begin)
            except HardlinkObservation as error:
                history.append({**error.evidence,'partial_counts':{k:v for k,v in getattr(error,'observation',{}).items() if k in ('allocated_bytes','logical_file_bytes','regular_files','directories','entries')}});error.history=list(history)
                _annotate(error,{},history)
                if attempt==2:raise
                remaining=self.limits['max_scan_seconds']-(time.monotonic()-begin)
                if remaining<=0:raise StorageLimit('time',error.observation) from error
                # Close completed before retry; no interrupted scan is accepted.
                time.sleep(min(.005,remaining))
                continue
            except BaseException as error:
                prior=getattr(error.__cause__ or error.__context__,'observation',{})
                _annotate(error,prior,history);raise
            result['scan_attempts']=attempt+1
            result['hardlink_observations']=history
            result['aggregate_entry_visit_bound']=3*self.limits['max_entries']
            elapsed=time.monotonic()-begin  # Includes final descriptor cleanup.
            result['elapsed_seconds']=elapsed
            if elapsed>self.limits['max_scan_seconds']:raise StorageLimit('time',result)
            result['qualification']+=' At most three fresh complete scans share one time budget; only singly linked regular files occur in an accepted scan. Transient links may occur between/during discarded observations.'
            return result
        raise AssertionError('unreachable storage retry state')

    def _scan(self,begin):
        observed={'allocated_bytes':0,'logical_file_bytes':0,'regular_files':0,'directories':0,'entries':0}
        limits=self.limits
        def enforce():
            for key,cap,reason in (('allocated_bytes','max_allocated_bytes','allocated'),('logical_file_bytes','max_logical_bytes','logical'),('entries','max_entries','entries')):
                if observed[key]>limits[cap]:raise StorageLimit(reason,observed)
            if time.monotonic()-begin>limits['max_scan_seconds']:raise StorageLimit('time',observed)
        def account(info,relative):
            if info.st_dev!=self.identity[0]:raise ValueError('storage entry crossed filesystem')
            if stat.S_ISREG(info.st_mode):
                if info.st_nlink!=1:raise HardlinkObservation(relative,info)
                observed['regular_files']+=1;observed['logical_file_bytes']+=info.st_size
            elif stat.S_ISDIR(info.st_mode):observed['directories']+=1
            else:raise ValueError('storage special file or symbolic link refused')
            observed['allocated_bytes']+=info.st_blocks*512
            enforce()
        flags=os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_CLOEXEC
        def visit(fd,depth,relative):
            info=os.fstat(fd);account(info,relative)
            entries=os.scandir(fd);iterator_primary=None
            try:
                for entry in entries:
                    observed['entries']+=1;enforce()
                    before=os.stat(entry.name,dir_fd=fd,follow_symlinks=False)
                    if stat.S_ISDIR(before.st_mode):
                        if depth+1>limits['max_depth']:raise StorageLimit('depth',observed)
                        child=os.open(entry.name,flags,dir_fd=fd)
                        primary=None
                        try:
                            opened=os.fstat(child)
                            if (before.st_dev,before.st_ino)!=(opened.st_dev,opened.st_ino):raise ValueError('storage directory changed while opening')
                            visit(child,depth+1,relative/entry.name)
                            current=os.stat(entry.name,dir_fd=fd,follow_symlinks=False)
                            if (current.st_dev,current.st_ino)!=(opened.st_dev,opened.st_ino):raise ValueError('storage directory changed during observation')
                        except BaseException as error:primary=error;raise
                        finally:_close(child,primary)
                    else:account(before,relative/entry.name)
            except BaseException as error:iterator_primary=error;raise
            finally:_cleanup(entries.close,iterator_primary)
        root_fd=os.open(self.root,flags);primary=None
        try:
            info=os.fstat(root_fd)
            if (info.st_dev,info.st_ino)!=self.identity:raise ValueError('owned storage root replaced')
            if self.root.resolve(strict=True)!=self.root:raise ValueError('owned storage root redirected')
            visit(root_fd,0,Path('.'))
            current=self.root.lstat()
            if not stat.S_ISDIR(current.st_mode) or (current.st_dev,current.st_ino)!=self.identity or self.root.resolve(strict=True)!=self.root:
                raise ValueError('owned storage root changed during observation')
            enforce()
            return {**observed,'elapsed_seconds':time.monotonic()-begin,'root':str(self.root),
                'root_device':self.identity[0],'root_inode':self.identity[1],
                'qualification':'Sampled non-atomic st_blocks accounting, including directories; no hard filesystem quota or inter-sample growth guarantee.'}
        except BaseException as error:
            primary=error;_annotate(error,observed,[]);raise
        finally:_close(root_fd,primary)
